SELECT la.*, lagroup.name groupName, (SELECT login_time FROM l_admin_login_record WHERE admin_id = la.id ORDER BY login_time DESC LIMIT 1) lastLoginTime FROM l_admin la LEFT JOIN l_admin_group lagroup ON la.group_id = lagroup.id
AND la.group_id = #{admin.groupId}
AND la.name LIKE CONCAT('%', #{admin.name}, '%')
AND la.status = #{admin.status}
ORDER BY la.id DESC LIMIT #{startNum}, #{size}

